import 'dart:typed_data';

import 'package:freshcart_domain/freshcart_domain.dart';

import 'builders.dart';

/// A hand-written [ItemRepository] stand-in.
///
/// Hand-written rather than generated by a mocking package: the domain has zero
/// runtime dependencies and its tests keep it that way, and an explicit fake
/// documents exactly what each use case is expected to call.
class FakeItemRepository implements ItemRepository {
  /// What [add] will return.
  Result<ShoppingItem> addResult = const Err<ShoppingItem>(
    Failure.unexpected('addResult not configured'),
  );

  /// What [save] will return. Defaults to echoing the saved item back.
  Result<ShoppingItem>? saveResult;

  /// Every argument list [add] was called with, in order.
  final List<
    ({
      ListId listId,
      String name,
      int quantity,
      ShopId? shopId,
      String? noteText,
    })
  >
  addCalls = [];

  /// Every item passed to [save], in order.
  final List<ShoppingItem> savedItems = [];

  @override
  Future<Result<ShoppingItem>> add({
    required ListId listId,
    required String name,
    int quantity = 1,
    ShopId? shopId,
    String? noteText,
  }) async {
    addCalls.add((
      listId: listId,
      name: name,
      quantity: quantity,
      shopId: shopId,
      noteText: noteText,
    ));
    return addResult;
  }

  @override
  Future<Result<ShoppingItem>> save(ShoppingItem item) async {
    savedItems.add(item);
    return saveResult ?? Ok(item);
  }

  @override
  Future<Result<List<ShoppingItem>>> byList(ListId listId) =>
      throw UnimplementedError();

  @override
  Future<Result<void>> remove(ItemId id) => throw UnimplementedError();

  @override
  Future<Result<int>> clearChecked(ListId listId) => throw UnimplementedError();

  @override
  Future<Result<int>> removeMany(ListId listId, List<ItemId> ids) =>
      throw UnimplementedError();

  @override
  Future<Result<int>> moveMany(
    ListId listId,
    List<ItemId> ids,
    ShopId? shopId,
  ) => throw UnimplementedError();

  @override
  Stream<Result<List<ShoppingItem>>> watchByList(ListId listId) =>
      throw UnimplementedError();

  @override
  Future<Result<List<String>>> suggestNames(ListId listId, String query) =>
      throw UnimplementedError();

  @override
  Future<Result<List<NameHistoryEntry>>> recentNames(ListId listId) =>
      throw UnimplementedError();
}

/// A hand-written [ListRepository] stand-in.
class FakeListRepository implements ListRepository {
  /// What [joinByCode] will return.
  Result<ShoppingList> joinResult = const Err<ShoppingList>(
    Failure.unexpected('joinResult not configured'),
  );

  /// What [create] will return.
  Result<ShoppingList> createResult = const Err<ShoppingList>(
    Failure.unexpected('createResult not configured'),
  );

  /// Every code [joinByCode] was called with, in order.
  final List<JoinCode> joinCalls = [];

  /// Every name [create] was called with, in order.
  final List<String> createCalls = [];

  /// What [rename] will return. Defaults to echoing the new name back.
  Result<void>? renameResult;

  /// Every argument list [rename] was called with, in order.
  final List<({ListId id, String name})> renameCalls = [];

  @override
  Future<Result<ShoppingList>> joinByCode(JoinCode code) async {
    joinCalls.add(code);
    return joinResult;
  }

  @override
  Future<Result<ShoppingList>> byId(ListId id) => throw UnimplementedError();

  @override
  Future<Result<List<ListSummary>>> summaries(List<ListId> ids) =>
      throw UnimplementedError();

  @override
  Future<Result<ShoppingList>> create({required String name}) async {
    createCalls.add(name);
    return createResult;
  }

  @override
  Future<Result<ListInvite>> openInvite(ListId id) =>
      throw UnimplementedError();

  @override
  Future<Result<void>> leave(ListId id) => throw UnimplementedError();

  @override
  Future<Result<void>> delete(ListId id) => throw UnimplementedError();

  @override
  Future<Result<void>> removeMember(ListId id, UserId userId) =>
      throw UnimplementedError();

  @override
  Future<Result<void>> transferOwnership(ListId id, UserId userId) =>
      throw UnimplementedError();

  @override
  Future<Result<List<ShoppingList>>> myLists() => throw UnimplementedError();

  @override
  Future<Result<void>> rename(ListId id, String name) async {
    renameCalls.add((id: id, name: name));
    return renameResult ?? const Ok(null);
  }

  @override
  Future<Result<void>> setClearCheckedAfterShopping(
    ListId id,
    bool value,
  ) => throw UnimplementedError();

  @override
  Stream<Result<ShoppingList>> watch(ListId id) => throw UnimplementedError();
}

/// A [ShopRepository] that records its calls and answers with whatever a test
/// configures.
class FakeShopRepository implements ShopRepository {
  /// What [create] will return. Defaults to echoing the new shop back.
  Result<Shop>? createResult;

  /// What [save] will return. Defaults to echoing the saved shop back.
  Result<Shop>? saveResult;

  /// Every argument list [create] was called with, in order.
  final List<({ListId listId, String name, HexColor color})> createCalls = [];

  /// Every shop passed to [save], in order.
  final List<Shop> savedShops = [];

  @override
  Future<Result<Shop>> create({
    required ListId listId,
    required String name,
    required HexColor color,
  }) async {
    createCalls.add((listId: listId, name: name, color: color));
    return createResult ?? Ok(buildShop(name: name, colorArgb: color.argb));
  }

  @override
  Future<Result<Shop>> save(Shop shop) async {
    savedShops.add(shop);
    return saveResult ?? Ok(shop);
  }

  @override
  Future<Result<List<Shop>>> byList(ListId listId) =>
      throw UnimplementedError();

  @override
  Future<Result<int>> itemCount(ShopId id) => throw UnimplementedError();

  @override
  Future<Result<void>> remove(
    ShopId id, {
    ShopItemDisposition disposition = ShopItemDisposition.untag,
    ShopId? moveTo,
  }) => throw UnimplementedError();
}

/// An [AuthRepository] that records its calls and answers with whatever a test
/// configures.
class FakeAuthRepository implements AuthRepository {
  /// What [setDisplayName] will return. Defaults to echoing the name back.
  Result<AuthUser>? setDisplayNameResult;

  /// Every name [setDisplayName] was called with, in order.
  final List<String> setDisplayNameCalls = [];

  @override
  Future<Result<AuthUser>> setDisplayName(String displayName) async {
    setDisplayNameCalls.add(displayName);
    return setDisplayNameResult ??
        Ok(
          AuthUser(
            id: testUser,
            displayName: displayName,
            isAnonymous: true,
          ),
        );
  }

  /// What [setAvatarColor] will return. Defaults to echoing the colour back.
  Result<AuthUser>? setAvatarColorResult;

  /// Every colour [setAvatarColor] was called with, in order.
  final List<HexColor> setAvatarColorCalls = [];

  @override
  Future<Result<AuthUser>> setAvatarColor(HexColor color) async {
    setAvatarColorCalls.add(color);
    return setAvatarColorResult ??
        Ok(
          AuthUser(
            id: testUser,
            displayName: 'Test User',
            isAnonymous: true,
            avatarColor: color,
          ),
        );
  }

  /// What [setAvatarPhoto] will return. Defaults to echoing a placeholder
  /// URL back.
  Result<AuthUser>? setAvatarPhotoResult;

  /// Every upload [setAvatarPhoto] was called with, in order.
  final List<Uint8List> setAvatarPhotoCalls = [];

  @override
  Future<Result<AuthUser>> setAvatarPhoto(Uint8List bytes) async {
    setAvatarPhotoCalls.add(bytes);
    return setAvatarPhotoResult ??
        Ok(
          AuthUser(
            id: testUser,
            displayName: 'Test User',
            isAnonymous: true,
            avatarPhotoUrl: 'https://example.test/avatars/test-user.jpg',
          ),
        );
  }

  /// What [clearAvatarPhoto] will return. Defaults to a user with no photo.
  Result<AuthUser>? clearAvatarPhotoResult;

  /// How many times [clearAvatarPhoto] was called.
  int clearAvatarPhotoCalls = 0;

  @override
  Future<Result<AuthUser>> clearAvatarPhoto() async {
    clearAvatarPhotoCalls++;
    return clearAvatarPhotoResult ??
        Ok(
          AuthUser(id: testUser, displayName: 'Test User', isAnonymous: true),
        );
  }

  @override
  AuthUser? get currentUser => throw UnimplementedError();

  @override
  UserId? get sessionUserId => throw UnimplementedError();

  @override
  Stream<AuthUser?> authStateChanges() => throw UnimplementedError();

  @override
  Future<Result<SignIn>> ensureSignedIn() => throw UnimplementedError();

  @override
  Future<Result<AuthUser>> linkGoogle() => throw UnimplementedError();

  @override
  Future<Result<String>> startLinkEmail(String email) async {
    startLinkEmailCalls.add(email);
    return const Ok('request-1');
  }

  /// Every email [startLinkEmail] was called with, in order.
  final List<String> startLinkEmailCalls = [];

  @override
  Future<Result<AuthUser>> finishLinkEmail({
    required String requestId,
    required String code,
    required String password,
  }) async {
    finishLinkEmailCalls.add(
      (requestId: requestId, code: code, password: password),
    );
    return finishLinkEmailResult ??
        Ok(AuthUser(id: testUser, displayName: 'Alex', isAnonymous: false));
  }

  /// What [finishLinkEmail] will return. Defaults to a now-linked user.
  Result<AuthUser>? finishLinkEmailResult;

  /// Every call to [finishLinkEmail], in order.
  final List<({String requestId, String code, String password})>
  finishLinkEmailCalls = [];

  /// What [signOut] will return. Defaults to success.
  Result<void> signOutResult = const Ok(null);

  /// Every call, in order, to the methods that sign-out uses, shared with
  /// the other fakes through [calls] so a test can check their order.
  List<String> calls = [];

  @override
  Future<Result<void>> signOut() async {
    calls.add('signOut');
    return signOutResult;
  }
}

/// A [NotificationRepository] for the sign-out tests: only
/// [unregisterDevice] is used.
class FakeNotificationRepository implements NotificationRepository {
  /// Creates the fake, recording into [calls].
  FakeNotificationRepository(this.calls);

  /// Shared call log (see [FakeAuthRepository.calls]).
  final List<String> calls;

  /// What [unregisterDevice] will return. Defaults to success.
  Result<void> unregisterResult = const Ok(null);

  @override
  Future<Result<void>> unregisterDevice() async {
    calls.add('unregisterDevice');
    return unregisterResult;
  }

  @override
  dynamic noSuchMethod(Invocation invocation) => throw UnimplementedError();
}

/// A [LocalDataRepository] that records its calls.
class FakeLocalDataRepository implements LocalDataRepository {
  /// Creates the fake, recording into [calls].
  FakeLocalDataRepository(this.calls);

  /// Shared call log (see [FakeAuthRepository.calls]).
  final List<String> calls;

  /// What [pendingChangeCount] returns.
  int pending = 0;

  @override
  Future<int> pendingChangeCount() async => pending;

  @override
  Future<void> clear() async => calls.add('clear');
}
